<nav class="sensecms-index-filters" aria-label="Post status"><?php foreach(['all'=>'All','published'=>'Published','draft'=>'Drafts','scheduled'=>'Scheduled','archived'=>'Archived']as$value=>$label): ?><a href="/content/posts?status=<?= $value ?>&facility=<?= (int)($facilityFilter??0) ?>" data-content-link class="<?= ($contentStatus??'all')===$value?'is-active':'' ?>"><?= $label ?><span><?= (int)($counts[$value]??0) ?></span></a><?php endforeach; ?></nav>
