<div class="sensecms-content-table card"><div class="sensecms-content-table-head"><span>Story</span><span>Classification</span><span>Publication</span><span>Actions</span></div><div class="sensecms-content-table-body"><?php foreach($items as$item):$archived=($item['status']??'')==='archived'; ?><article class="sensecms-content-row"><div class="sensecms-content-identity"><i data-lucide="newspaper"></i><span><strong><?= $escape($item['title']??'Untitled post') ?></strong><small><?= $escape(($item['facility_name']??'Facility').' · '.($item['slug']??'')) ?></small></span></div><div class="sensecms-content-metrics"><span><i data-lucide="tag"></i><?= $escape($item['category']??'Uncategorised') ?></span><span><b><?= (int)($item['translation_count']??0) ?></b> languages</span></div><div><span class="sensecms-lifecycle is-<?= $escape((string)($item['status']??'draft')) ?>"><i data-lucide="<?= $archived?'archive':(($item['status']??'')==='published'?'circle-check':'clock-3') ?>"></i><?= $escape(ucfirst((string)($item['status']??'draft'))) ?></span><?php if(!empty($item['published_at'])): ?><small class="sensecms-date"><?= $escape(date('M j, Y · H:i',strtotime((string)$item['published_at']))) ?></small><?php endif; ?></div><div class="sensecms-row-actions"><a href="/content/posts/<?= (int)$item['id'] ?>/edit" data-content-link aria-label="Edit post"><i data-lucide="pencil"></i></a><?php if(!$archived): ?><form method="post" action="/content/posts/<?= (int)$item['id'] ?>/duplicate"><input type="hidden" name="csrf" value="<?= $escape($csrf) ?>"><button aria-label="Duplicate post"><i data-lucide="copy"></i></button></form><?php endif; ?><form method="post" action="/content/posts/<?= (int)$item['id'] ?>/<?= $archived?'restore':'archive' ?>" data-sensecms-confirm="<?= $archived?'Restore this post as a draft?':'Archive this post without deleting its translations?' ?>"><input type="hidden" name="csrf" value="<?= $escape($csrf) ?>"><button class="<?= $archived?'is-restore':'is-danger' ?>" aria-label="<?= $archived?'Restore':'Archive' ?> post"><i data-lucide="<?= $archived?'archive-restore':'archive' ?>"></i></button></form></div></article><?php endforeach; ?><?php if(!$items): ?><div class="sensecms-content-empty"><i data-lucide="newspaper"></i><strong>No posts found</strong><span>Adjust the filters or create a new school story.</span></div><?php endif; ?></div><footer class="sensecms-index-pagination"><span><?= (int)($pagination['total']??0) ?> posts</span><div><a data-content-link class="<?= ($pagination['page']??1)<=1?'is-disabled':'' ?>" href="/content/posts?status=<?= $escape($contentStatus??'all') ?>&facility=<?= (int)($facilityFilter??0) ?>&q=<?= rawurlencode((string)($contentQuery??'')) ?>&page=<?= max(1,(int)($pagination['page']??1)-1) ?>"><i data-lucide="chevron-left"></i></a><b><?= (int)($pagination['page']??1) ?> / <?= (int)($pagination['pages']??1) ?></b><a data-content-link class="<?= ($pagination['page']??1)>=($pagination['pages']??1)?'is-disabled':'' ?>" href="/content/posts?status=<?= $escape($contentStatus??'all') ?>&facility=<?= (int)($facilityFilter??0) ?>&q=<?= rawurlencode((string)($contentQuery??'')) ?>&page=<?= min((int)($pagination['pages']??1),(int)($pagination['page']??1)+1) ?>"><i data-lucide="chevron-right"></i></a></div></footer></div></section>
